import System.Exception;import System.ArgumentException;import System.ArgumentOutOfRangeException;import System.Globalization.NumberFormatInfo;import System.Type;import System.Int32;import System.SByte;import System.Byte;import System.UInt16;import System.UInt32;import System.Decimal;import System.Globalization.*;import System.Reflection.*;import System.Runtime.Serialization.*;import System.Text.NormalizationForm;import System.TypeCode;import System.DayOfWeek;import System.DateTimeKind;import java.nio.file.*;import java.util.*;
class EnumTypeReceiverGuardsProbe {
 interface Action{void run();}
 static String units(String s){if(s==null)return "~";StringJoiner j=new StringJoiner(",");for(char c:s.toCharArray())j.add(Integer.toString(c));return j.toString();}
 static String text(String s){if(s.equals("~"))return null;StringBuilder b=new StringBuilder();if(!s.isEmpty())for(String u:s.split(","))b.append((char)Integer.parseInt(u));return b.toString();}
 static int[] sizes(String s){if(s.equals("~"))return null;if(s.isEmpty())return new int[0];String[] p=s.split(",");int[] a=new int[p.length];for(int i=0;i<a.length;i++)a[i]=Integer.parseInt(p[i]);return a;}
 static String csv(int[] a){StringJoiner j=new StringJoiner(",");for(int v:a)j.add(Integer.toString(v));return j.toString();}
 static String outcome(Action a){try{a.run();return "OK";}catch(Exception e){return String.join("|","ERR",e.getClass().getName(),units(e.get_Message()),Integer.toString(e.get_HResult()),units(e instanceof ArgumentException x?x.get_ParamName():null),e instanceof ArgumentOutOfRangeException x&&x.get_ActualValue()!=null?x.get_ActualValue().toString():"~");}}
 static void check(String a,String e,String c){if(!a.equals(e))throw new AssertionError(c+" actual="+a+" expected="+e);}
 static String flag(boolean b){return b?"1":"0";}
 static Object enumValue(String name,int v){return switch(name){case "System.Globalization.DigitShapes"->DigitShapes.FromInt32(v);case "System.Globalization.NumberStyles"->NumberStyles.FromInt32(v);case "System.Globalization.TimeSpanStyles"->TimeSpanStyles.FromInt32(v);case "System.Globalization.DateTimeStyles"->DateTimeStyles.FromInt32(v);case "System.Text.NormalizationForm"->NormalizationForm.FromInt32(v);case "System.Reflection.GenericParameterAttributes"->GenericParameterAttributes.FromInt32(v);case "System.Reflection.BindingFlags"->BindingFlags.FromInt32(v);case "System.Reflection.MemberTypes"->MemberTypes.FromInt32(v);case "System.Reflection.CallingConventions"->CallingConventions.FromInt32(v);case "System.Reflection.MethodImplAttributes"->MethodImplAttributes.FromInt32(v);case "System.Runtime.Serialization.StreamingContextStates"->StreamingContextStates.FromInt32(v);case "System.TypeCode"->Arrays.stream(TypeCode.values()).filter(e->e.get_Value()==v).findFirst().orElseThrow();case "System.DayOfWeek"->DayOfWeek.values()[v];case "System.DateTimeKind"->DateTimeKind.values()[v];case "System.Reflection.ParameterAttributes"->Arrays.stream(ParameterAttributes.values()).filter(e->e.get_Value()==v).findFirst().orElseThrow();default->throw new AssertionError(name);};}
 static Object value(String kind,String value,String enumType){return switch(kind){case "null"->null;case "object"->new Object();case "string"->text(value);case "enum"->enumValue(enumType,Integer.parseInt(value));case "int32"->Integer.valueOf(value);case "int32Facade"->new Int32(Integer.parseInt(value));case "int16"->Short.valueOf(value);case "int64"->Long.valueOf(value);case "sbyte"->new SByte(java.lang.Byte.parseByte(value));case "sbytePrimitive"->java.lang.Byte.valueOf(value);case "byte"->new Byte(Short.parseShort(value));case "uint16"->new UInt16(Integer.parseInt(value));case "uint32"->new UInt32(Long.parseLong(value));case "uint64"->new java.math.BigInteger(value);case "bool"->value.equals("1");case "char"->Character.valueOf((char)Integer.parseInt(value));case "single"->Float.valueOf(value);case "double"->Double.valueOf(value);case "decimal"->Decimal.Parse(value);default->throw new AssertionError(kind);};}
 static Type receiver(String name){for(String suffix:new String[]{"[]","*","&"})if(name.endsWith(suffix)){Type root=Type.GetType(name.substring(0,name.length()-suffix.length()));return suffix.equals("[]")?root.MakeArrayType():suffix.equals("*")?root.MakePointerType():root.MakeByRefType();}return Type.GetType(name);}
 static String query(Type type,String method,Object value){return outcome(()->{switch(method){case "GetEnumNames"->type.GetEnumNames();case "GetEnumValues"->type.GetEnumValues();case "GetEnumValuesAsUnderlyingType"->type.GetEnumValuesAsUnderlyingType();case "GetEnumUnderlyingType"->type.GetEnumUnderlyingType();case "GetEnumName"->type.GetEnumName(value);case "IsEnumDefined"->type.IsEnumDefined(value);default->throw new AssertionError();}});}
 public static void main(String[] args)throws java.lang.Exception{int groups=0;for(String line:Files.readAllLines(Path.of(args[0]))){String[] p=line.split("\t",-1);Type t=receiver(p[0]);if(t==null||t.get_IsEnum())throw new AssertionError("receiver "+p[0]);Object v=p[2].equals("noarg")?null:value(p[2],p[3],p[4]);check(query(t,p[1],v),p[5],line);groups++;}java.lang.System.out.println("PASS enum receiver guards groups="+groups);}
}
